<div><h4>Product</h4><ul><li><a href="${n}/#benefits">Benefits</a></li><li><a href="${n}/#see">Features</a></li><li><a href="${n}/#how">How It Works</a></li><li><a href="${n}/#calc">Savings</a></li><li><a href="${n}/#pricing">Pricing</a></li><li><a href="${n}/#faq">FAQ</a></li></ul></div>
